\documentclass[border=5pt]{standalone}
\usepackage{pgfplots}
\pgfplotsset{compat=1.18}
\usepackage{pgfplotstable}

\begin{document}
\begin{tikzpicture}
\begin{axis}[
    title={人数变化图},
    xlabel={年份},
    ylabel={人数},
    xmin=2010, xmax=2023,
    ymin=0, ymax=120,
    xtick={2010,2012,2014,2016,2018,2020,2022},
    ytick={0,20,40,60,80,100,120},
    legend pos=north west,
    grid=major,
    grid style={dashed,gray!30},
    width=12cm,
    height=8cm,
    tick label style={font=\small},
    label style={font=\small},
    title style={font=\large\bfseries}
]

% 示例数据 - 请替换为您的实际数据
\addplot[
    color=blue,
    mark=square,
    line width=1pt,
    mark size=2pt
    ]
    coordinates {
    (2010, 50)
    (2012, 65)
    (2014, 78)
    (2016, 85)
    (2018, 92)
    (2020, 105)
    (2022, 98)
    };
    \addlegendentry{人数变化}

\end{axis}
\end{tikzpicture}
\end{document}
